insert into public.admin_content(content_type, title, slug, excerpt, body, status, seo_title, seo_description, published_at)
select 'RETURN_POLICY', 'ফেরত ও অর্থ ফেরত নীতি', 'return-refund-policy', 'পণ্য না মিললে কীভাবে সহায়তা পাবেন।',
E'BikriKoro-তে নিরাপদ কেনাকাটার জন্য অর্ডার, payment এবং delivery-এর তথ্য সংরক্ষণ করুন।\n\n১. পণ্য description, category, quantity বা promised feature-এর সঙ্গে না মিললে delivery পাওয়ার পর যত দ্রুত সম্ভব Order Detail থেকে সমস্যা জানান। Screenshot, chat এবং প্রাসঙ্গিক প্রমাণ যুক্ত করুন।\n\n২. Digital product হলে access পাওয়ার পর ব্যবহার, download বা license key পরিবর্তন করার আগে সমস্যা জানান। ভুল বা অসম্পূর্ণ delivery যাচাইয়ের জন্য seller ও buyer উভয়ের বক্তব্য দেখা হবে।\n\n৩. Physical product হলে পণ্যের অবস্থা, ছবি এবং package-এর প্রমাণ রাখুন। ব্যবহারের কারণে ক্ষতি, buyer-এর ভুল বা description-এ আগে থেকে উল্লেখ থাকা বিষয় সাধারণত refund-এর আওতায় পড়ে না।\n\n৪. Valid dispute হলে BikriKoro order status, payment record, chat এবং evidence দেখে সিদ্ধান্ত নেবে। অনুমোদিত refund buyer wallet বা মূল payment flow-এ policy অনুযায়ী ফেরত দেওয়া হবে।\n\n৫. Platform-এর বাইরে payment, OTP, password বা account access দেওয়া হলে সেই লেনদেনের দায় platform নিতে পারবে না। সহায়তার জন্য Contact ও Help পেজ ব্যবহার করুন।',
'PUBLISHED', 'ফেরত ও অর্থ ফেরত নীতি | BikriKoro', 'BikriKoro marketplace-এ পণ্য না মিললে return, dispute এবং refund সহায়তার নিয়ম।', now()
where not exists (select 1 from public.admin_content where content_type='RETURN_POLICY' and slug='return-refund-policy');
